"""
B&R ACOPOS Parameter Definitions
Auto-generated from acp10par.h and supplemental trace names in convert.py -- do not edit manually.
Supplemental types follow explicit decoding rules in BrMotionNwTraceFile.py.
UINT/USINT are unsigned 2/1-byte values; NIL marks commands with no scalar value.
STR denotes ASCII with unknown capacity; data_type="" means the type is unconfirmed.
Generic 32-bit trace fallback decoding is not treated as evidence of a parameter type.
Supplemental parameters use their trace name as description.

Function-block parameters support instances 0 through 7: ID = base ID + instance.
Existing names refer to instance 0; explicit names use the _INSTANCE_0 ... _INSTANCE_7 suffix.
Example: ACP10PAR.ARITH_MODE.instance(3) is ACP10PAR.ARITH_MODE_INSTANCE_3.
The corresponding block must be created on the drive via FUNCTION_BLOCK_CREATE before use.
See https://help.br-automation.com/#/de/6/ncsoftware/acp10_drivefunctions/acopos_funktionsbausteine/funktion.html
"""

from enum import IntEnum


class ACP10PAR(IntEnum):
    """ACOPOS parameter IDs with IEC data type and description."""

    data_type: str
    description: str
    function_block: str
    instance_number: int

    def __new__(cls, value: int, data_type: str = "", description: str = "",
                function_block: str = "", instance_number: int = 0) -> "ACP10PAR":
        obj = int.__new__(cls, value)
        obj._value_ = value
        obj.data_type = data_type
        obj.description = description
        obj.function_block = function_block
        obj.instance_number = instance_number
        return obj

    def instance(self, number: int) -> "ACP10PAR":
        """Select FB instance 0..7; this does not create the block on the drive."""
        if not self.function_block:
            raise ValueError(f"{self.name} is not a multi-instance function-block parameter")
        if isinstance(number, bool) or not isinstance(number, int):
            raise TypeError("Instance number must be an integer")
        if not 0 <= number <= 7:
            raise ValueError("Instance number must be between 0 and 7")
        return ACP10PAR(int(self) - self.instance_number + number)

